    {
      "subject": "B1 #1",
      "verdict": "confirmed",
      "reason": "S2 lines 1-8 (codes 99460, 0170, 99462, etc.) total $7,400 denied A27 under member [MEMBER_1]; D3 shows baby's bill with insurance_paid -$4,946.75 and patient_balance $1,490.25 but no EOB for PATIENT_2 in the papers."
    },
    {
      "subject": "B2 #1",
      "verdict": "confirmed",
      "reason": "S14 (2025-04-01) for PATIENT_2 from Cradleview-Obstetrix shows patient_balance $275.00; no insurance statement for PATIENT_2 exists; 349 days elapsed since 2025-04-01 to 2026-03-16."
    },
    {
      "subject": "P1 #1",
      "verdict": "confirmed",
      "reason": "S1 page 1 of 4, S2 page 2 of 4, S3 page 4 of 4 — page 3 is missing."
    },
    {
      "subject": "F1 #2",
      "verdict": "problem",
      "reason": "Policy quote (memorial-2026-05#scale-mrh) gives 85% discount for 201%-250% FPG, not 90%; the claimed $1,341.23 assumes 90% off $1,490.25."
    },
    {
      "subject": "F2 #1",
      "verdict": "problem",
      "reason": "Deadline 2026-04-01 derived from twelve months after last insurance payment (2025-04-01), but the cited federal quote (federal-501r#application-period) points to 240 days after first post-discharge statement (2025-04-05 → 2025-12-01), which has passed; the memorial quote allows up to one year after service (2026-02-11) or twelve months after last insurance payment — the letter mixes two different rules."
    },
    {
      "subject": "letter itemized",
      "verdict": "confirmed",
      "reason": "Account 30955 (S12) covers 2024-11-25 to 2025-01-06; account 409798605 (D1) covers 2025-02-11 to 2025-02-13; third account placeholder. Florida statute quotes not in case but letter's factual references are correct."
    },
    {
      "subject": "letter dispute",
      "verdict": "confirmed",
      "reason": "S10 (account 44932556) lines 1-2 are duplicate code 01960 on 2025-02-11 at $4,944 each; dispute request matches the evidence."
    },
    {
      "subject": "letter application",
      "verdict": "problem",
      "reason": "Letter claims 90% discount at 212.3% FPG, but policy quote (memorial-2026-05#scale-mrh) shows 85% for 201%-250% FPG; the application period claim before 2026-04-01 is only valid under the twelve-months-after-last-payment rule, not the one-year-after-service rule (which ended 2026-02-11)."
    }
  ]
}
